"""Golden-output regression tests for the TEMPO forecaster."""

import numpy as np
import pytest

from sktime.datasets import load_airline
from sktime.forecasting.tempo import TEMPOForecaster
from sktime.tests.test_switch import run_test_for_class

_SEED = 42

# Reference forecasts were generated by the original TEMPO implementation,
